package com.example.demo.adapters.jdbc;

import com.example.demo.domain.Article;
import com.example.demo.ports.search.ArticleSearch;
import java.util.List;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public final class JdbcArticleSearch implements ArticleSearch {

    private static final String SQL =
            """
            select id, title, body
              from articles
             where search_vector @@ websearch_to_tsquery('english', :query)
             order by ts_rank(search_vector, websearch_to_tsquery('english', :query)) desc
             limit :limit
            """;

    private final JdbcClient jdbc;

    public JdbcArticleSearch(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public List<Article> matching(String query, int limit) {
        return jdbc.sql(SQL)
                .param("query", query)
                .param("limit", limit)
                .query(Article.class)
                .list();
    }
}
